// package httpadapter_test (reuses newOpsRig/opsCall/ovPath from ops_handler_test.go)
func TestChallenge_RateLiteralForms(t *testing.T) {
	for _, c := range []string{`1e2`, `100.0`, `1E2`, `-0`, `0.0`, `1.0e1`, `10000.00`} {
		rig := newOpsRig(true)
		rec := opsCall(rig.mux, http.MethodPut, ovPath(opsEvent), "ops", `{"rate_per_sec":`+c+`,"reason":"abc"}`)
		t.Logf("rate=%s -> %d %s sets=%v", c, rec.Code, rec.Body.String(), rig.store.sets)
	}
}

type panicAuditor struct{}
func (panicAuditor) Record(context.Context, app.AuditEntry) error { panic("pg driver panic") }
func TestChallenge_AuditorPanic(t *testing.T) {
	st := &fakeOverrideStore{configured: true}
	logs := &strings.Builder{}
	log := slog.New(slog.NewTextHandler(logs, nil))
	mux := http.NewServeMux()
	httpadapter.NewOpsHandler(&fakeState{}, app.NewOpsOverride(st, panicAuditor{}, log), log).Routes(mux)
	defer func() { r := recover(); t.Logf("panic=%v sets=%v errorLog=%v", r != nil, st.sets, strings.Contains(logs.String(), "level=ERROR")) }()
	opsCall(mux, http.MethodPut, ovPath(opsEvent), "ops", `{"rate_per_sec":0,"reason":"abc"}`)
}
// output: panic=true sets=[0] errorLog=false

